COMMENT ON SCHEMA public IS 'Driving Licence Reminder application relations and Liquibase migration metadata; no cross-schema application links.';
COMMENT ON COLUMN user_account.id IS 'Application-generated opaque UUID primary key; never derived from personal data.';
COMMENT ON COLUMN user_account.identity_issuer IS 'Case-sensitive external identity namespace, not an environment service URL.';
COMMENT ON COLUMN user_account.identity_subject IS 'Case-sensitive opaque external subject; do not store national ID or credentials.';
COMMENT ON COLUMN user_account.created_at IS 'Creation instant in UTC, including timezone information.';
COMMENT ON COLUMN user_account.deleted_at IS 'UTC logical deactivation instant; later service code must revoke access and delivery immediately.';
COMMENT ON COLUMN web_session.id IS 'Application-generated opaque UUID primary key; never derived from personal data.';
COMMENT ON COLUMN web_session.user_id IS 'Owning local user account UUID; scope access to the authenticated account.';
COMMENT ON COLUMN web_session.token_hash IS 'Exactly 32 bytes of SHA-256 over a high-entropy random bearer token; no raw token.';
COMMENT ON COLUMN web_session.created_at IS 'Creation instant in UTC, including timezone information.';
COMMENT ON COLUMN web_session.expires_at IS 'UTC absolute session expiry instant; must be after creation.';
COMMENT ON COLUMN web_session.revoked_at IS 'UTC revocation instant; NULL means not explicitly revoked, not proof of browser permission.';
COMMENT ON COLUMN status_check.id IS 'Application-generated opaque UUID primary key; never derived from personal data.';
COMMENT ON COLUMN status_check.user_id IS 'Owning local user account UUID; scope access to the authenticated account.';
COMMENT ON COLUMN status_check.requested_at IS 'UTC start of a durable refresh attempt.';
COMMENT ON COLUMN status_check.completed_at IS 'UTC completion instant, NULL while the operation is pending.';
COMMENT ON COLUMN status_check.outcome IS 'Normalized local operation result; pending is incomplete, unknown requires reconciliation.';
COMMENT ON COLUMN status_check.trace_id IS 'Random per-operation correlation UUID; never a reusable session token or personal identifier.';
COMMENT ON COLUMN status_check.xroad_request_id IS 'Optional bounded X-Road correlation identifier, not a request or response body.';
COMMENT ON COLUMN status_check.source_code IS 'Logical Transport Administration through X-Road provenance key; authority/medical source contract pending.';
COMMENT ON COLUMN status_check.driving_status IS 'Local valid, at_risk or invalid assessment; not legal proof of entitlement.';
COMMENT ON COLUMN status_check.reason_code IS 'Safe translated assessment explanation key required for at_risk or invalid.';
COMMENT ON COLUMN status_check.medical_requirement IS 'required, not_required or unknown; absence of data does not imply not_required.';
COMMENT ON COLUMN status_check.status_changed IS 'NULL for first success; otherwise compare driving status to the previous successful check under a user lock.';
COMMENT ON COLUMN status_check.error_code IS 'Bounded safe internal error translation key; never a raw provider message or payload.';
COMMENT ON COLUMN driving_licence.id IS 'Application-generated opaque UUID primary key; never derived from personal data.';
COMMENT ON COLUMN driving_licence.check_id IS 'Successful local status-check snapshot containing this cached observation.';
COMMENT ON COLUMN driving_licence.check_outcome IS 'Constant successful outcome enforces linkage only to a successful check.';
COMMENT ON COLUMN driving_licence.document_status IS 'Normalized cached document state: valid, expired, revoked, suspended or unknown.';
COMMENT ON COLUMN driving_licence.issued_on IS 'Registry calendar issue date when supplied; not a timestamp.';
COMMENT ON COLUMN driving_licence.expires_on IS 'Registry calendar expiry date, NULL when unknown or not supplied; not a timestamp.';
COMMENT ON COLUMN licence_category.licence_id IS 'Local cached driving-licence UUID, not a registry document number.';
COMMENT ON COLUMN licence_category.category_code IS 'One supported Estonian driving category in the cached licence; part of its composite primary key.';
COMMENT ON COLUMN medical_certificate.id IS 'Application-generated opaque UUID primary key; never derived from personal data.';
COMMENT ON COLUMN medical_certificate.check_id IS 'Successful local status-check snapshot containing this cached observation.';
COMMENT ON COLUMN medical_certificate.check_outcome IS 'Constant successful outcome enforces linkage only to a successful check.';
COMMENT ON COLUMN medical_certificate.certificate_status IS 'Normalized cached certificate state only: valid, expired, revoked or unknown; no clinical details.';
COMMENT ON COLUMN medical_certificate.issued_on IS 'Registry calendar issue date when supplied; not a timestamp.';
COMMENT ON COLUMN medical_certificate.expires_on IS 'Registry calendar expiry date, NULL when unknown or not supplied; not a timestamp.';
COMMENT ON COLUMN reminder_preference.user_id IS 'Owning local user account UUID; scope access to the authenticated account.';
COMMENT ON COLUMN reminder_preference.enabled IS 'Explicit local opt-in; defaults false, and does not override browser permission.';
COMMENT ON COLUMN reminder_preference.updated_at IS 'Last local settings change instant in UTC; update atomically with the settings.';
COMMENT ON COLUMN reminder_interval.user_id IS 'Owning local user account UUID; scope access to the authenticated account.';
COMMENT ON COLUMN reminder_interval.days_before IS 'Selected or frozen reminder lead time in calendar days: 90, 30 or 7.';
COMMENT ON COLUMN web_push_subscription.id IS 'Application-generated opaque UUID primary key; never derived from personal data.';
COMMENT ON COLUMN web_push_subscription.user_id IS 'Owning local user account UUID; scope access to the authenticated account.';
COMMENT ON COLUMN web_push_subscription.encrypted_subscription IS 'Variable-length externally encrypted browser endpoint and delivery key bundle; never a plaintext credential.';
COMMENT ON COLUMN web_push_subscription.encryption_key_ref IS 'External vault key and version reference; never key material.';
COMMENT ON COLUMN web_push_subscription.created_at IS 'Creation instant in UTC, including timezone information.';
COMMENT ON COLUMN web_push_subscription.revoked_at IS 'UTC revocation instant; NULL means not explicitly revoked, not proof of browser permission.';
COMMENT ON COLUMN notification.id IS 'Application-generated opaque UUID primary key; never derived from personal data.';
COMMENT ON COLUMN notification.user_id IS 'Owning local user account UUID; scope access to the authenticated account.';
COMMENT ON COLUMN notification.check_id IS 'Snapshot from the same user that justified this frozen notification target.';
COMMENT ON COLUMN notification.document_kind IS 'Frozen driving_licence or medical_certificate target type, consistent with exactly one target FK.';
COMMENT ON COLUMN notification.licence_id IS 'Local cached driving-licence UUID, not a registry document number.';
COMMENT ON COLUMN notification.medical_certificate_id IS 'Local cached medical-certificate UUID when this is a medical reminder.';
COMMENT ON COLUMN notification.expires_on IS 'Frozen relevant registry expiry date; composite target FK verifies this against the referenced snapshot.';
COMMENT ON COLUMN notification.days_before IS 'Selected or frozen reminder lead time in calendar days: 90, 30 or 7.';
COMMENT ON COLUMN notification.scheduled_at IS 'Planned UTC delivery instant computed from expiry and selected lead days by the future worker.';
COMMENT ON COLUMN notification.channel IS 'in_app or optional browser web_push; not a mobile delivery channel.';
COMMENT ON COLUMN notification.subscription_id IS 'Same-user browser route required only for web_push; no multi-device fan-out assumed.';
COMMENT ON COLUMN notification.state IS 'Durable outbox lifecycle: pending, processing, sent, failed or cancelled.';
COMMENT ON COLUMN notification.claimed_until IS 'UTC processing lease expiry, present only while processing; supports authorised recovery.';
COMMENT ON COLUMN notification.sent_at IS 'UTC successful delivery acceptance instant; non-NULL only for sent notifications.';
COMMENT ON COLUMN notification.error_code IS 'Bounded safe internal error translation key; never a raw provider message or payload.';
COMMENT ON COLUMN notification.created_at IS 'Creation instant in UTC, including timezone information.';
COMMENT ON COLUMN notification_attempt.id IS 'Application-generated opaque UUID primary key; never derived from personal data.';
COMMENT ON COLUMN notification_attempt.notification_id IS 'Logical notification being delivered; attempts are removed with its bounded history.';
COMMENT ON COLUMN notification_attempt.attempt_number IS 'Positive sequence unique within a logical notification.';
COMMENT ON COLUMN notification_attempt.started_at IS 'UTC start of this delivery attempt.';
COMMENT ON COLUMN notification_attempt.completed_at IS 'UTC completion instant, NULL while the operation is pending.';
COMMENT ON COLUMN notification_attempt.outcome IS 'Normalized local operation result; pending is incomplete, unknown requires reconciliation.';
COMMENT ON COLUMN notification_attempt.error_code IS 'Bounded safe internal error translation key; never a raw provider message or payload.';
COMMENT ON COLUMN notification_attempt.trace_id IS 'Random per-operation correlation UUID; never a reusable session token or personal identifier.';
COMMENT ON COLUMN audit_event.id IS 'Application-generated opaque UUID primary key; never derived from personal data.';
COMMENT ON COLUMN audit_event.occurred_at IS 'UTC audit event occurrence instant; distinct from export/ingestion time.';
COMMENT ON COLUMN audit_event.actor_user_id IS 'Optional pseudonymous acting account; deletion blocked until independent custodian anonymizes the link.';
COMMENT ON COLUMN audit_event.subject_user_id IS 'Optional affected account; deletion blocked until independent custodian anonymizes the link.';
COMMENT ON COLUMN audit_event.actor_kind IS 'user, operator, system or anonymous; a user actor requires an account link.';
COMMENT ON COLUMN audit_event.action_code IS 'Bounded internal event/action code; no free text, identifiers or data payload.';
COMMENT ON COLUMN audit_event.outcome IS 'Normalized local operation result; pending is incomplete, unknown requires reconciliation.';
COMMENT ON COLUMN audit_event.error_code IS 'Bounded safe internal error translation key; never a raw provider message or payload.';
COMMENT ON COLUMN audit_event.trace_id IS 'Random per-operation correlation UUID; never a reusable session token or personal identifier.';
